const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('vi-VN',{maximumFractionDigits:10}).format(n)+' ₫';
let state={product:'',entries:[]},saved=[];try{saved=JSON.parse(localStorage.getItem('giasat-reports')||'[]')}catch{}
const period=()=>$('#period').value,account=()=>$('#account').value;
const matching=()=>state.entries.filter(e=>e.period===period()&&e.account===account());
const valid=()=>matching().filter(e=>!e.exclude);
const prices=()=>valid().filter(e=>e.type==='reseller').map(e=>Number(e.price)).sort((a,b)=>a-b);
function mid(a){return a.length?(a[Math.floor((a.length-1)/2)]+a[Math.ceil((a.length-1)/2)])/2:null}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function research(){const p=$('#product').value.trim();if(!p)return; if(state.product&&state.product!==p&&state.entries.length&&!confirm('Bắt đầu sản phẩm mới? Hãy lưu báo cáo hiện tại nếu muốn giữ lại.'))return; if(state.product!==p)state={product:p,entries:[]}; render()}
$('#searchForm').onsubmit=e=>{e.preventDefault();research()};$$('.suggestions button').forEach(b=>b.onclick=()=>{$('#product').value=b.textContent;research()});
function render(){const p=state.product;$('#reportName').textContent=p||'Bắt đầu với một sản phẩm';$('#reportMeta').textContent=p?'Báo cáo thu thập thủ công · '+new Date().toLocaleDateString('vi-VN')+' · '+account()+' · '+(period()==='month'?'1 tháng':'1 năm'):'Dữ liệu rõ nguồn. So sánh đúng gói. Quyết định có căn cứ.';const links=$('#researchLinks');links.hidden=!p;links.innerHTML=p?[['01','Giá bán lẻ Việt Nam',p+' giá bán Việt Nam'],['02','Giá chính hãng',p+' official pricing'],['03','Tin mới & khuyến mãi',p+' khuyến mãi thay đổi giá']].map(([n,t,q])=>'<a target="_blank" rel="noopener noreferrer" href="https://www.google.com/search?q='+encodeURIComponent(q)+'&tbs=qdr:m6">'+n+' · '+t+' ↗</a>').join(''):'';
 const a=prices(),m=mid(a),official=valid().filter(e=>e.type==='official').map(e=>Number(e.price));$('#official').textContent=official.length?[...new Set(official)].map(money).join(' / '):'Chưa có dữ liệu';$('#median').textContent=m===null?'Chưa có dữ liệu':money(m);$('#range').textContent=a.length?'Thấp '+money(a[0])+' · Cao '+money(a.at(-1)):'Chỉ tính các bản ghi cùng loại';$('#confidence').textContent=state.entries.length?'Thấp':'Chưa đánh giá';$('#confidenceNote').textContent=state.entries.length?'Nguồn nhập thủ công, chưa kiểm chứng độc lập':'Chưa có nguồn để đối chiếu';
const rows=matching();$('#rowCount').textContent=rows.length;$('#empty').hidden=!!rows.length;$('#sourceCount').textContent=state.entries.length+' nguồn';$('#rows').innerHTML=rows.map(e=>'<tr class="'+(e.exclude?'excluded':'')+'"><td><b>'+esc(e.seller)+'</b><small>'+esc(e.type==='official'?'Chính hãng':'Reseller')+' · '+esc(e.account)+(e.exclude?' · Đã loại: '+esc(e.reason):'')+'</small></td><td><b>'+money(Number(e.price))+'</b></td><td>'+esc(e.plan)+'<small>'+(e.period==='month'?'1 tháng':'1 năm')+'</small></td><td>'+esc(e.warranty||'Chưa có dữ liệu')+'</td><td>'+esc(e.promo||'Chưa có dữ liệu')+'</td><td><a target="_blank" rel="noopener noreferrer" href="'+esc(e.url)+'">'+esc(new URL(e.url).hostname)+' ↗</a><small>'+esc(e.date||'Không rõ ngày đăng')+'</small><button class="remove" data-id="'+e.id+'" aria-label="Xóa nguồn" style="font-size:8px;padding:3px 6px;margin-top:6px">Xóa</button></td></tr>').join('');$$('.remove').forEach(b=>b.onclick=()=>{state.entries=state.entries.filter(e=>e.id!==b.dataset.id);render()});
$('#marketing').textContent=rows.filter(e=>e.promo).slice(0,4).map(e=>e.seller+': '+e.promo).join(' • ')||'Thông điệp, bảo hành và ưu đãi sẽ xuất hiện khi bạn thêm nguồn.';$('#strategy').textContent=a.length>=3?'Tham khảo '+money(m)+' cho '+account().toLowerCase()+', '+(period()==='month'?'1 tháng':'1 năm')+'. Cân nhắc giá trung bình + bảo hành tốt; cần đối chiếu giá vốn và quyền phân phối.':'Cần ít nhất 3 giá reseller cùng loại để tham khảo mức giá trung vị.';$('#savedCount').textContent=saved.length;
}
$('#period').onchange=render;$('#account').onchange=render;
function add(){if(!state.product){$('#product').focus();toast('Nhập tên sản phẩm trước khi thêm nguồn.');return}$('#entryForm').reset();$('#entryForm').elements.period.value=period();$('#entryForm').elements.account.value=account();$('#entryDialog').showModal()}
$('#add').onclick=add;$('#firstAdd').onclick=add;$('#closeDialog').onclick=()=>$('#entryDialog').close();
$('#entryForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),entry=Object.fromEntries(f);if(!/^https?:$/.test(new URL(entry.url).protocol)){toast('Nguồn phải dùng đường dẫn HTTP hoặc HTTPS.');return}entry.exclude=f.has('exclude');if(entry.exclude&&!entry.reason.trim()){toast('Vui lòng ghi lý do loại giá.');return}if(entry.date&&new Date(entry.date)>new Date()){toast('Ngày nguồn không thể nằm trong tương lai.');return}const cutoff=new Date();cutoff.setMonth(cutoff.getMonth()-6);if(entry.date&&new Date(entry.date)<cutoff&&!confirm('Nguồn cũ hơn 6 tháng. Chỉ dùng nếu không có nguồn mới. Bạn đã kiểm tra chưa?'))return;entry.id=crypto.randomUUID();state.entries.push(entry);$('#entryDialog').close();render();toast('Đã thêm nguồn vào báo cáo.')};
function markdown(){const a=prices(),m=mid(a),rows=matching(),clean=s=>String(s||'Chưa có dữ liệu').replace(/[|\r\n]/g,' ');let text='# '+state.product+'\n\n## 📊 1. Tổng quan thị trường\n- Giá chính hãng: '+$('#official').textContent+'\n- Khoảng giá reseller: '+(a.length?'thấp nhất '+money(a[0])+' / trung vị '+money(m)+' / cao nhất '+money(a.at(-1)):'Chưa có dữ liệu')+'\n- Xu hướng: Chưa có dữ liệu so sánh theo thời gian.\n\n## 🏷️ 2. Bảng so sánh đối thủ\n| Đối thủ | Giá | Gói & thời hạn | Hình thức | Bảo hành | Khuyến mãi / Điểm nhấn | Nguồn |\n| :--- | :--- | :--- | :--- | :--- | :--- | :--- |\n';let words=text.split(/\s+/).length;for(const e of rows){const line='| '+[e.seller+' ('+(e.type==='official'?'Chính hãng':'Reseller')+')',money(Number(e.price)),e.plan+' / '+(e.period==='month'?'1 tháng':'1 năm'),e.account,e.warranty,e.promo,'['+new URL(e.url).hostname+']('+e.url+') · '+(e.date||'Không rõ ngày')+(e.exclude?' · Loại: '+e.reason:'')].map(clean).join(' | ')+' |\n';if(words+line.split(/\s+/).length>340)break;text+=line;words+=line.split(/\s+/).length}text+='\n## 📣 3. Cách đối thủ quảng cáo\n'+(rows.filter(e=>e.promo).slice(0,4).map(e=>'- '+clean(e.seller)+': '+clean(e.promo).split(/\s+/).slice(0,10).join(' ')).join('\n')||'Chưa có dữ liệu')+'\n\n## 🆕 4. Điểm mới đáng chú ý\nChưa có dữ liệu đã kiểm chứng.\n\n## 💡 5. Gợi ý chiến lược định giá\n'+(a.length>=3?'Mức tham khảo: '+money(m)+'. Giá trung bình + bảo hành tốt; cần kiểm tra giá vốn và quyền phân phối.':'Chưa đủ 3 giá reseller cùng loại để đề xuất.')+'\nRủi ro: biến động giá và chính sách nhà phát hành.\n\n## ✅ 6. Độ tin cậy\nThấp: dữ liệu nhập thủ công, chưa kiểm chứng độc lập.\n';return text}
$('#export').onclick=()=>{if(!state.product){toast('Chọn sản phẩm trước khi xuất.');return}const blob=new Blob([markdown()],{type:'text/markdown;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='bao-cao-giasat.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Đã xuất báo cáo. Bảng dài được rút gọn để giới hạn 500 từ.')};
$('#save').onclick=()=>{if(!state.product){toast('Chọn sản phẩm trước khi lưu.');return}try{saved.unshift({...structuredClone(state),savedAt:new Date().toISOString()});localStorage.setItem('giasat-reports',JSON.stringify(saved));render();toast('Đã lưu trên trình duyệt này.')}catch{toast('Trình duyệt không cho phép lưu dữ liệu.')}};
$$('nav button').forEach(b=>b.onclick=()=>{['research','saved','method'].forEach(id=>$('#'+id).hidden=id!==b.dataset.view);$$('nav button').forEach(n=>n.classList.toggle('active',n===b));$('#crumb').textContent=b.querySelector('span').textContent;if(b.dataset.view==='saved')renderSaved()});
function renderSaved(){$('#savedList').innerHTML=saved.length?saved.map((s,i)=>'<div class="saved-item"><b>'+esc(s.product)+'<p style="font-size:10px">'+new Date(s.savedAt).toLocaleString('vi-VN')+' · '+s.entries.length+' nguồn</p></b><button data-open="'+i+'">Mở báo cáo →</button><button data-delete="'+i+'" aria-label="Xóa báo cáo">×</button></div>').join(''):'<section class="search-card">Chưa có báo cáo đã lưu. Bắt đầu nghiên cứu và nhấn Lưu.</section>';$$('[data-open]').forEach(b=>b.onclick=()=>{state=structuredClone(saved[+b.dataset.open]);$('#product').value=state.product;$$('nav button')[0].click();render()});$$('[data-delete]').forEach(b=>b.onclick=()=>{saved.splice(+b.dataset.delete,1);try{localStorage.setItem('giasat-reports',JSON.stringify(saved))}catch{}renderSaved();render()})}
render();
